import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"سادھائی کے وسائل کی کھلاؤ کا طریقہ کار","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0018-修炼资源开放机制.md","filePath":"ur/0018-修炼资源开放机制.md"}'),o={name:"ur/0018-修炼资源开放机制.md"};function d(e,t,h,n,u,s){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="سادھائی-کے-وسائل-کی-کھلاؤ-کا-طریقہ-کار" tabindex="-1">سادھائی کے وسائل کی کھلاؤ کا طریقہ کار <a class="header-anchor" href="#سادھائی-کے-وسائل-کی-کھلاؤ-کا-طریقہ-کار" aria-label="Permalink to &quot;سادھائی کے وسائل کی کھلاؤ کا طریقہ کار&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>18</td></tr><tr><td>ماڈیول</td><td>کائنات کے قوانین اور سادھائی کے نظام</td></tr><tr><td>کلیدی الفاظ</td><td>وسائل کی کھلاؤ، سادھائی کے وسائل، تقسیم کا طریقہ کار، یکجہتی مخالف، وسائل کی انصاف</td></tr></tbody></table><h2 id="اولًا-سادھائی-کے-وسائل-کی-کھلاؤ-کے-طریقہ-کار-کا-پس-منظر-اور-اہمیت" tabindex="-1">اولًا. سادھائی کے وسائل کی کھلاؤ کے طریقہ کار کا پس منظر اور اہمیت <a class="header-anchor" href="#اولًا-سادھائی-کے-وسائل-کی-کھلاؤ-کے-طریقہ-کار-کا-پس-منظر-اور-اہمیت" aria-label="Permalink to &quot;اولًا. سادھائی کے وسائل کی کھلاؤ کے طریقہ کار کا پس منظر اور اہمیت&quot;">​</a></h2><p>لوٹ مار کے دور میں، سادھائی کے وسائل سب سے اہم تنازعہ کا موضوع تھے۔ روحانی شریانیں، دواؤں کے کھیت، توانائی کی کان کی شریانیں، آسمانی خزانے، سادھائی کے خفیہ علاقے اور دیگر وسائل چند طاقتور افراد اور فرقوں کے قبضے میں تھے، اور نچلی سطح کے عام لوگ تقریباً کوئی باقاعدہ سادھائی کا وسائل حاصل نہیں کر سکتے تھے۔ اس وسائل کی یکجہتی نے نہ صرف سنگین طبقاتی استحکام پیدا کیا، بلکہ وسائل کے تنازعات کی وجہ سے لاتعداد جنگیں اور قتل عام بھی ہوئے۔ وسائل کی یکجہتی لوٹ مار کے نظام کی معاشی بنیاد ہے — جب تک وسائل چند لوگوں کے قبضے میں ہیں، &quot;ہر ایک کے پاس راستہ ہے&quot; صرف ایک خالی جملہ رہے گا۔</p><p>اینکر سمبیوٹک تہذیب کے قیام کے بعد، &quot;سادھائی کے وسائل کی کھلاؤ&quot; کو سب سے اہم ادارہ جاتی تبدیلیوں میں سے ایک کے طور پر اپنایا گیا۔ سادھائی کے وسائل کی کھلاؤ کے طریقہ کار کا بنیادی مقصد یہ ہے: وسائل کی یکجہتی کو توڑنا، اس بات کو یقینی بنانا کہ ہر زندگی کو بنیادی سادھائی کے وسائل مل سکیں، اور ساتھ ہی زیادہ محنت زیادہ فائدہ کی تقسیم کے طریقہ کار کے ذریعے وسائل کے موثر استعمال اور مسلسل تخلیق کی حوصلہ افزائی کرنا۔ وسائل کی کھلاؤ کا مطلب &quot;وسائل کی مساوی تقسیم&quot; نہیں ہے، بلکہ &quot;وسائل تک منصفانہ رسائی&quot; ہے — بنیادی ضروریات کی ضمانت کی شرط پر، وسائل کی تقسیم انفرادی شراکت سے منسلک ہے، اور ساتھ ہی کسی بھی قسم کی وسائل کی یکجہتی سختی سے ممنوع ہے۔</p><p>سادھائی کے وسائل کی کھلاؤ کے طریقہ کار کی اہمیت یہ ہے: یہ معاشی بنیاد سے لوٹ مار کی مٹی کو اکھاڑ پھینکتا ہے، تین سو سادھائی کے نظاموں کی حقیقی عامیت کے لیے مادی ضمانت فراہم کرتا ہے، &quot;ہر ایک کے پاس راستہ ہے&quot; کے سماجی مقصد کے لیے وسائل کی حمایت فراہم کرتا ہے، اور تمام نسلوں کی مشترکہ ترقی کے لیے منصفانہ نقطہ آغاز بناتا ہے۔</p><h2 id="ثانیًا-سادھائی-کے-وسائل-کی-درجہ-بندی-اور-درجہ-بندی" tabindex="-1">ثانیًا. سادھائی کے وسائل کی درجہ بندی اور درجہ بندی <a class="header-anchor" href="#ثانیًا-سادھائی-کے-وسائل-کی-درجہ-بندی-اور-درجہ-بندی" aria-label="Permalink to &quot;ثانیًا. سادھائی کے وسائل کی درجہ بندی اور درجہ بندی&quot;">​</a></h2><h3 id="_2-1-وسائل-کی-درجہ-بندی" tabindex="-1">2.1 وسائل کی درجہ بندی <a class="header-anchor" href="#_2-1-وسائل-کی-درجہ-بندی" aria-label="Permalink to &quot;2.1 وسائل کی درجہ بندی&quot;">​</a></h3><p>ہینگ یوآن ژو میں سادھائی کے وسائل کو نوعیت اور استعمال کے لحاظ سے درج ذیل بڑی اقسام میں تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>وسائل کی قسم</th><th>مخصوص مواد</th><th>بنیادی استعمال</th></tr></thead><tbody><tr><td>توانائی کے وسائل</td><td>روحانی شریانیں، توانائی کی کان کی شریانیں، روحانی توانائی کے کرسٹل، اصل توانائی کے ٹکڑے وغیرہ</td><td>سادھائی کے لیے درکار توانائی کی فراہمی</td></tr><tr><td>دواؤں کے وسائل</td><td>روحانی دوائیں، امرت کی جڑیاں، دواؤں کی تیاری کے مواد، تیار شدہ دوائیں وغیرہ</td><td>سادھائی میں مدد، زخموں کا علاج، رکاوٹوں کو عبور کرنا</td></tr><tr><td>آلات کے وسائل</td><td>سادھائی کے ساز، قانون کے آلات، دوگنا کرنے والے آلات، خلائی آلات وغیرہ</td><td>سادھائی کی کارکردگی میں اضافہ، قانون کے کنٹرول میں مدد</td></tr><tr><td>خلائی وسائل</td><td>سادھائی کے خفیہ علاقے، روحانی توانائی کے ارتکاز کے علاقے، قانون کے ادراک کے کمرے، الگ تھلگ جگہیں وغیرہ</td><td>خاص سادھائی کا ماحول فراہم کرنا</td></tr><tr><td>علم کے وسائل</td><td>سادھائی کے طریقے، سادھائی کے تجربات، قانون کے تحقیقی مواد، تکنیکی دستاویزات وغیرہ</td><td>سادھائی کے لیے نظریاتی اور طریقہ کار کی رہنمائی فراہم کرنا</td></tr><tr><td>حیاتیاتی وسائل</td><td>روحانی جانور، روحانی پودے، معاہدہ شدہ زندگی، سمبیوٹک وجود وغیرہ</td><td>سادھائی میں مدد، سمبیوٹک چکر، خصوصی صلاحیتیں</td></tr><tr><td>کائناتی وسائل</td><td>غیر ترقی یافتہ کائناتی علاقے، کائناتی راستے کے استعمال کے حقوق، کائناتی بنیادی ٹکڑے وغیرہ</td><td>بڑے پیمانے پر سادھائی اور ترقی کی جگہ فراہم کرنا</td></tr></tbody></table><h3 id="_2-2-وسائل-کی-درجہ-بندی" tabindex="-1">2.2 وسائل کی درجہ بندی <a class="header-anchor" href="#_2-2-وسائل-کی-درجہ-بندی" aria-label="Permalink to &quot;2.2 وسائل کی درجہ بندی&quot;">​</a></h3><p>تمام سادھائی کے وسائل کو نایابیت اور قدر کے لحاظ سے پانچ درجوں میں تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>درجہ</th><th>نام</th><th>نایابیت</th><th>تقسیم کا طریقہ</th></tr></thead><tbody><tr><td>پہلا درجہ</td><td>عام وسائل</td><td>وسیع پیمانے پر تقسیم، بھرپور ذخائر</td><td>مفت کھلاؤ یا کم قیمت پر تقسیم</td></tr><tr><td>دوسرا درجہ</td><td>بہترین وسائل</td><td>نسبتاً عام، درمیانے ذخائر</td><td>بنیادی تقسیم + شراکت کے بدلے</td></tr><tr><td>تیسرا درجہ</td><td>نایاب وسائل</td><td>نسبتاً نایاب، محدود ذخائر</td><td>شراکت کے بدلے + درخواست کی منظوری</td></tr><tr><td>چوتھا درجہ</td><td>مہاکاوی وسائل</td><td>انتہائی نایاب، بہت کم ذخائر</td><td>مسابقتی تقسیم + تہذیب کی سطح کے منصوبوں کو ترجیح</td></tr><tr><td>پانچواں درجہ</td><td>افسانوی وسائل</td><td>انتہائی نایاب، تقریباً معدوم</td><td>تہذیب کے اعلیٰ ترین فیصلہ ساز ادارے کی خصوصی تقسیم</td></tr></tbody></table><h2 id="ثالثًا-وسائل-کی-کھلاؤ-کے-بنیادی-اصول" tabindex="-1">ثالثًا. وسائل کی کھلاؤ کے بنیادی اصول <a class="header-anchor" href="#ثالثًا-وسائل-کی-کھلاؤ-کے-بنیادی-اصول" aria-label="Permalink to &quot;ثالثًا. وسائل کی کھلاؤ کے بنیادی اصول&quot;">​</a></h2><h3 id="_3-1-بنیادی-ضمانت-کا-اصول" tabindex="-1">3.1 بنیادی ضمانت کا اصول <a class="header-anchor" href="#_3-1-بنیادی-ضمانت-کا-اصول" aria-label="Permalink to &quot;3.1 بنیادی ضمانت کا اصول&quot;">​</a></h3><p>ہر زندگی کو بنیادی سادھائی کو برقرار رکھنے کے لیے درکار پہلے اور دوسرے درجے کے وسائل حاصل کرنے کا حق ہے۔ بنیادی ضمانت کے وسائل &quot;ہر ایک کے پاس راستہ ہے ضمانتی نظام&quot; کے ذریعے مفت یا کم قیمت پر تقسیم کیے جاتے ہیں، کوئی رکاوٹ نہیں، کوئی امتیاز نہیں۔ بنیادی ضمانت کے معیار کو تمام نسلوں کی جمہوریہ پارلیمنٹ تہذیب کے وسائل کی صورتحال اور ترقی کے مرحلے کے مطابق باقاعدگی سے ایڈجسٹ کرتی ہے، اس بات کو یقینی بناتی ہے کہ ضمانت کی سطح تہذیب کی برداشت کی صلاحیت کے مطابق ہو۔</p><h3 id="_3-2-زیادہ-محنت-زیادہ-فائدہ-کا-اصول" tabindex="-1">3.2 زیادہ محنت زیادہ فائدہ کا اصول <a class="header-anchor" href="#_3-2-زیادہ-محنت-زیادہ-فائدہ-کا-اصول" aria-label="Permalink to &quot;3.2 زیادہ محنت زیادہ فائدہ کا اصول&quot;">​</a></h3><p>بنیادی ضمانت کے اوپر، تیسرے درجے اور اس سے اوپر کے وسائل کی تقسیم میں فرد کی سمبیوٹک نیٹ ورک میں شراکت کی قدر کو بنیادی بنیاد کے طور پر لیا جاتا ہے۔ شراکت جتنی زیادہ، بدلے میں ملنے والے وسائل اتنے ہی زیادہ اور درجہ اتنے ہی بلند ہوتے ہیں۔ زیادہ محنت زیادہ فائدہ کا اصول سادھکوں کو اپنی سطح کو بڑھانے اور تہذیب کے لیے بڑی شراکت کرنے کی ترغیب دیتا ہے، اور ساتھ ہی اس بات کو یقینی بناتا ہے کہ وسائل ان افراد اور گروہوں کی طرف بہہ جائیں جو انہیں مؤثر طریقے سے استعمال کرنے کے قابل ہوں۔</p><h3 id="_3-3-یکجہتی-مخالف-اصول" tabindex="-1">3.3 یکجہتی مخالف اصول <a class="header-anchor" href="#_3-3-یکجہتی-مخالف-اصول" aria-label="Permalink to &quot;3.3 یکجہتی مخالف اصول&quot;">​</a></h3><p>کسی بھی فرد، تنظیم، نسل کو سادھائی کے وسائل پر یکجہتی قائم کرنے سے سختی سے منع کیا گیا ہے۔ یکجہتی مخالف کے مخصوص اقدامات میں شامل ہیں:</p><ul><li>کسی ایک فرد یا تنظیم کے پاس تیسرے درجے اور اس سے اوپر کے وسائل تہذیب کے کل ذخائر کے 1% سے زیادہ نہیں ہو سکتے</li><li>ذخیرہ کر کے قیمت بڑھانا ممنوع ہے — وسائل کے مالک وسائل کی کمی کے وقت بدنیتی پر ذخیرہ جمع کر کے قیمت بڑھا نہیں سکتے</li><li>خصوصی قبضے سے منع — عوامی وسائل (جیسے عوامی روحانی شریانیں، عوامی خفیہ علاقے وغیرہ) کو نجی طور پر خصوصی طور پر قبضے میں نہیں لیا جا سکتا</li><li>یکجہتی مخالف قانون کی خلاف ورزی کرنے والے رویے پر اینکر عدالت کی طرف سے سخت سزا ہوگی، جس میں وسائل ضبط کرنا، شراکت کی قدر کو صفر کرنا، سادھائی کے اجازت ناموں پر پابندی لگانا وغیرہ شامل ہیں</li></ul><h3 id="_3-4-پائیدار-استعمال-کا-اصول" tabindex="-1">3.4 پائیدار استعمال کا اصول <a class="header-anchor" href="#_3-4-پائیدار-استعمال-کا-اصول" aria-label="Permalink to &quot;3.4 پائیدار استعمال کا اصول&quot;">​</a></h3><p>تمام وسائل کی ترقی اور استعمال کو پائیدار اصول پر عمل کرنا چاہیے، اور جھیل سوکھا کر مچھلی پکڑنے جیسے لوٹ مار کی کھدائی کی اجازت نہیں ہے۔ مخصوص تقاضوں میں شامل ہیں:</p><ul><li>وسائل کی ترقی کی رفتار وسائل کی قدرتی تخلیق نو کی رفتار سے زیادہ نہیں ہو سکتی (غیر قابل تجدید وسائل کے لیے، متبادل منصوبہ بنانا ضروری ہے)</li><li>وسائل کی ترقی کے لیے ماحولیاتی اثرات کا جائزہ لینا ضروری ہے، ماحولیاتی نظام کو ناقابل واپسی نقصان سے بچانا</li><li>خطرے سے دوچار وسائل کے لیے، ممنوعہ کھدائی یا محدود کھدائی کی پالیسی لاگو کرنا، وسائل کی تخلیق نو کی صلاحیت کی حفاظت کرنا</li><li>تکنیکی ذرائع (جیسے قانون کی انجینئرنگ، دوگنا کرنے کی ٹیکنالوجی وغیرہ) کے ذریعے نایاب وسائل کی مصنوعی کاشت اور ترکیب کی حوصلہ افزائی کرنا، قدرتی وسائل پر انحصار کو کم کرنا</li></ul><h3 id="_3-5-کھلا-اور-شفاف-اصول" tabindex="-1">3.5 کھلا اور شفاف اصول <a class="header-anchor" href="#_3-5-کھلا-اور-شفاف-اصول" aria-label="Permalink to &quot;3.5 کھلا اور شفاف اصول&quot;">​</a></h3><p>وسائل کی تقسیم کا عمل کھلا اور شفاف ہونا چاہیے، تمام جانداروں کی نگرانی قبول کرنا چاہیے:</p><ul><li>تمام عوامی وسائل کے ذخائر، تقسیم، ترقی کی صورتحال کو باقاعدگی سے معاشرے کے سامنے کھولا جاتا ہے</li><li>وسائل کی تقسیم کے معیار، عمل، نتائج کھلے اور قابل جانچ ہیں</li><li>وسائل کی تقسیم کے اپیل کا طریقہ کار قائم کرنا، جن افراد کو تقسیم کے نتائج پر اعتراض ہے وہ نظر ثیزی کے لیے درخواست دے سکتے ہیں</li><li>اینکر عدالت کے ماتحت &quot;وسائل کی انصاف کمیٹی&quot;، خاص طور پر وسائل کی تقسیم کی انصاف اور قانونی حیثیت کی نگرانی کرتی ہے</li></ul><h2 id="رابعًا-وسائل-کی-کھلاؤ-کے-مخصوص-طریقہ-کار" tabindex="-1">رابعًا. وسائل کی کھلاؤ کے مخصوص طریقہ کار <a class="header-anchor" href="#رابعًا-وسائل-کی-کھلاؤ-کے-مخصوص-طریقہ-کار" aria-label="Permalink to &quot;رابعًا. وسائل کی کھلاؤ کے مخصوص طریقہ کار&quot;">​</a></h2><h3 id="_4-1-مشترکہ-پیداوار-معاہدہ-کا-طریقہ-کار" tabindex="-1">4.1 مشترکہ پیداوار معاہدہ کا طریقہ کار <a class="header-anchor" href="#_4-1-مشترکہ-پیداوار-معاہدہ-کا-طریقہ-کار" aria-label="Permalink to &quot;4.1 مشترکہ پیداوار معاہدہ کا طریقہ کار&quot;">​</a></h3><p>مشترکہ پیداوار معاہدہ سادھائی کے وسائل کی کھلاؤ کا بنیادی ادارہ جاتی ڈیزائن ہے، اور اس کا بنیادی طریقہ کار &quot;زیادہ محنت زیادہ فائدہ کی تقسیم کے اصول&quot; دستاویز میں تفصیل سے بیان کیا گیا ہے۔ وسائل کی کھلاؤ کے شعبے میں، مشترکہ پیداوار معاہدے کی مخصوص اطلاق میں شامل ہیں:</p><ul><li><strong>روحانی شریانیں کا معاہدہ</strong>: عوامی روحانی شریانیں سادھک گروپ یا نسلی برادری کو معاہدے پر دینا، معاہدہ دار شریان کی دیکھ بھال اور پائیدار ترقی کے لیے ذمہ دار ہے، اور شریان کی پیداوار کا ایک مخصوص تناسب حاصل کرتا ہے</li><li><strong>دواؤں کے کھیت کا معاہدہ</strong>: عوامی دواؤں کے کھیت کاشت کی صلاحیت رکھنے والے سادھک کو معاہدے پر دینا، معاہدہ دار روحانی دواؤں کی کاشت اور دیکھ بھال کے لیے ذمہ دار ہے، اور فصل تناسب کے مطابق تقسیم کی جاتی ہے</li><li><strong>خفیہ علاقوں کی انتظامیہ</strong>: عوامی سادھائی کے خفیہ علاقے پیشہ ور ٹیم کو انتظامیہ کے لیے سونپنا، انتظامیہ دار خفیہ علاقے کی دیکھ بھال اور سلامتی کے لیے ذمہ دار ہے، اور صارف مناسب استعمال فیس ادا کرتا ہے</li><li><strong>وسائل کی تلاش</strong>: سادھکوں کو غیر ترقی یافتہ علاقوں میں وسائل کی تلاش میں حصہ لینے کی ترغیب دینا، تلاش کرنے والے کو نئے دریافت شدہ وسائل پر معاہدے کا اولویتی حق حاصل ہے</li></ul><h3 id="_4-2-شراکت-کی-قدر-کے-بدلے-کا-طریقہ-کار" tabindex="-1">4.2 شراکت کی قدر کے بدلے کا طریقہ کار <a class="header-anchor" href="#_4-2-شراکت-کی-قدر-کے-بدلے-کا-طریقہ-کار" aria-label="Permalink to &quot;4.2 شراکت کی قدر کے بدلے کا طریقہ کار&quot;">​</a></h3><p>سمبیوٹک تہذیب نے ایک متحد &quot;شراکت کی قدر کے بدلے کا نظام&quot; قائم کیا ہے، جس میں سادھک سمبیوٹک نیٹ ورک میں شراکت کر کے شراکت کی قدر جمع کر سکتے ہیں، اور پھر شراکت کی قدر سے مختلف سادھائی کے وسائل بدل سکتے ہیں:</p><ul><li>شراکت کی قدر حاصل کرنے کے طریقوں میں شامل ہیں: سادھائی کی ترقی، علم کی اشتراک، ٹیکنالوجی کی جدت، عوامی خدمت، ماحولیاتی بحالی، تہذیب کی حفاظت وغیرہ</li><li>بدلے کا نظام &quot;واضح قیمت&quot; نافذ کرتا ہے، ہر وسائل کی واضح شراکت کی قدر کی قیمت ہے، اور قیمت وسائل کی نایابیت اور طلب کے مطابق متحرک طور پر ایڈجسٹ کی جاتی ہے</li><li>بدلے کا نظام &quot;پیشگی&quot; فنکشن کی حمایت کرتا ہے — صلاحیت رکھنے والے سادھک وسائل کے بدلے کے لیے ایک مخصوص مقدار میں شراکت کی قدر پیشگی لے سکتے ہیں، اور مستقبل میں شراکت کر کے اس کی ادائیگی کر سکتے ہیں</li><li>بدلے کا نظام اینکر نیٹ ورک سے ریئل ٹائم منسلک ہے، شراکت کی قدر کے ریکارڈ اور بدلے کی سلامتی اور قابل اعتمادی کو یقینی بناتا ہے</li></ul><h3 id="_4-3-عوامی-وسائل-کی-مفت-کھلاؤ-کا-طریقہ-کار" tabindex="-1">4.3 عوامی وسائل کی مفت کھلاؤ کا طریقہ کار <a class="header-anchor" href="#_4-3-عوامی-وسائل-کی-مفت-کھلاؤ-کا-طریقہ-کار" aria-label="Permalink to &quot;4.3 عوامی وسائل کی مفت کھلاؤ کا طریقہ کار&quot;">​</a></h3><p>درج ذیل قسم کے وسائل تمام جانداروں کے لیے مفت کھولے جاتے ہیں:</p><ul><li><strong>علم کے وسائل</strong>: تین سو سادھائی کے نظاموں کے بنیادی طریقے، عوامی سادھائی کے تجربات، بنیادی قانون کے تحقیقی مواد وغیرہ</li><li><strong>پہلے درجے کے توانائی کے وسائل</strong>: بنیادی روحانی توانائی، عام توانائی کے کرسٹل اور دیگر وسیع پیمانے پر تقسیم شدہ نچلے درجے کے توانائی کے وسائل</li><li><strong>عوامی سادھائی کی جگہیں</strong>: عوامی سادھائی کے کمرے، بنیادی قانون کے ادراک کے کمرے، عام الگ تھلگ جگہیں وغیرہ</li><li><strong>بنیادی طبی وسائل</strong>: بنیادی علاج کے طریقے، عام زخموں کی دوائیں، بنیادی بحالی خدمات وغیرہ</li><li><strong>بنیادی تعلیمی وسائل</strong>: بنیادی سادھائی کورسز، ابتدائی استاد کی رہنمائی، عام سادھائی کے آلات کا استعمال وغیرہ</li></ul><h3 id="_4-4-خاص-وسائل-کی-ہدایت-شدہ-تقسیم-کا-طریقہ-کار" tabindex="-1">4.4 خاص وسائل کی ہدایت شدہ تقسیم کا طریقہ کار <a class="header-anchor" href="#_4-4-خاص-وسائل-کی-ہدایت-شدہ-تقسیم-کا-طریقہ-کار" aria-label="Permalink to &quot;4.4 خاص وسائل کی ہدایت شدہ تقسیم کا طریقہ کار&quot;">​</a></h3><p>چوتھے، پانچویں درجے جیسے نایاب وسائل کے لیے، &quot;ہدایت شدہ تقسیم&quot; کا طریقہ کار نافذ کیا جاتا ہے:</p><ul><li>نایاب وسائل کو ترجیحاً تہذیب کی سطح کے اہم منصوبوں (جیسے اینکر کی تعمیر، کائناتی ترقی، ٹیکنالوجی کی کامیابی وغیرہ) میں تقسیم کیا جاتا ہے</li><li>خاص ضروریات رکھنے والے افراد کے لیے (جیسے اہم سطح کو عبور کرنے کے لیے مخصوص وسائل کی ضرورت، خاص زخموں کے علاج کے لیے نایاب دواؤں کی ضرورت وغیرہ)، درخواست کی منظوری کے ذریعے ہدایت شدہ تقسیم حاصل کر سکتے ہیں</li><li>نایاب وسائل کی تقسیم کا منصوبہ تمام نسلوں کی جمہوریہ پارلیمنٹ کے ماتحت &quot;وسائل کی تقسیم کمیٹی&quot; تیار کرتی ہے، اور پارلیمنٹ کی منظوری کے بعد عمل میں لایا جاتا ہے</li><li>ہدایت شدہ تقسیم کے نتائج معاشرے کے سامنے کھولے جاتے ہیں، اور نگرانی قبول کی جاتی ہے</li></ul><h2 id="خامسًا-وسائل-کی-تخلیق-اور-پائیدار-ترقی" tabindex="-1">خامسًا. وسائل کی تخلیق اور پائیدار ترقی <a class="header-anchor" href="#خامسًا-وسائل-کی-تخلیق-اور-پائیدار-ترقی" aria-label="Permalink to &quot;خامسًا. وسائل کی تخلیق اور پائیدار ترقی&quot;">​</a></h2><p>سادھائی کے وسائل کی کھلاؤ صرف &quot;موجودہ ذخائر کی تقسیم&quot; نہیں ہے، بلکہ &quot;اضافے کی تخلیق&quot; بھی ہے۔ سمبیوٹک تہذیب وسائل کی مصنوعی تخلیق اور پائیدار ترقی کی بھرپور حوصلہ افزائی کرتی ہے:</p><h3 id="_5-1-وسائل-کی-مصنوعی-کاشت" tabindex="-1">5.1 وسائل کی مصنوعی کاشت <a class="header-anchor" href="#_5-1-وسائل-کی-مصنوعی-کاشت" aria-label="Permalink to &quot;5.1 وسائل کی مصنوعی کاشت&quot;">​</a></h3><ul><li><strong>روحانی دواؤں کی مصنوعی کاشت</strong>: قانون کی انجینئرنگ ٹیکنالوجی کے ذریعے، مصنوعی ماحول میں مختلف روحانی دواؤں کی کاشت کرنا، جنگلی روحانی دواؤں پر انحصار کو کم کرنا</li><li><strong>توانائی کی مصنوعی پیداوار</strong>: مادہ توانائی کی تبدیلی کے آلات، قانون کی گونج جنریٹر وغیرہ ٹیکنالوجی کے ذریعے، مصنوعی طور پر روحانی توانائی اور توانائی کے کرسٹل پیدا کرنا</li><li><strong>روحانی جانوروں کی مصنوعی افزائش</strong>: روحانی جانوروں کی افزائش کے مراکز قائم کرنا، مختلف روحانی جانوروں کی مصنوعی کاشت کرنا، جنگلی روحانی جانوروں کی آبادی کی حفاظت کرنا</li><li><strong>خفیہ علاقوں کی مصنوعی تعمیر</strong>: خلائی قانون ٹیکنالوجی کے ذریعے، مصنوعی طور پر سادھائی کے خفیہ علاقے تعمیر کرنا، سادھائی کی جگہوں کی فراہمی میں اضافہ کرنا</li></ul><h3 id="_5-2-وسائل-کی-چکری-استعمال" tabindex="-1">5.2 وسائل کی چکری استعمال <a class="header-anchor" href="#_5-2-وسائل-کی-چکری-استعمال" aria-label="Permalink to &quot;5.2 وسائل کی چکری استعمال&quot;">​</a></h3><ul><li><strong>توانائی کی بازیافت</strong>: توانائی کی بازیافت کا نظام قائم کرنا، سادھائی کے عمل میں ضائع ہونے والی توانائی، جنگ میں پھیلنے والی توانائی وغیرہ کو بازیافت کر کے دوبارہ استعمال کرنا</li><li><strong>دواؤں کے باقیات کی پروسیسنگ</strong>: دواؤں کی تیاری کے بعد کے باقیات کی دوسری نکاسی اور پروسیسنگ کرنا، دواؤں کے وسائل کے استعمال کی کارکردگی کو بڑھانا</li><li><strong>آلات کی بازیافت اور دوبارہ تعمیر</strong>: بیکار ہونے والے سادھائی کے آلات کی بازیافت اور دوبارہ تعمیر کرنا، مواد کے ضیاع کو کم کرنا</li><li><strong>جگہوں کی چکری استعمال</strong>: استعمال ختم ہونے والی الگ تھلگ جگہوں، عارضی سادھائی کی جگہوں وغیرہ کو صاف کر کے چکری طور پر استعمال کرنا</li></ul><h3 id="_5-3-وسائل-کے-متبادل-ٹیکنالوجی" tabindex="-1">5.3 وسائل کے متبادل ٹیکنالوجی <a class="header-anchor" href="#_5-3-وسائل-کے-متبادل-ٹیکنالوجی" aria-label="Permalink to &quot;5.3 وسائل کے متبادل ٹیکنالوجی&quot;">​</a></h3><ul><li>نایاب وسائل کے متبادل کی تحقیق اور ترقی کی حوصلہ افزائی کرنا، تکنیکی ذرائع کے ذریعے &quot;عام مواد سے نایاب مواد کو تبدیل کرنا&quot; کو عملی جامہ پہنانا</li><li>غیر قابل تجدید افسانوی درجے کے وسائل کے لیے، سخت حفاظتی اور استعمال کا منصوبہ بنانا، اور ساتھ ہی متبادل ٹیکنالوجی کی تحقیق اور ترقی میں سرمایہ کاری بڑھانا</li><li>&quot;وسائل کے متبادل ٹیکنالوجی کی تحقیق اور ترقی کا فنڈ&quot; قائم کرنا، متعلقہ تحقیقی منصوبوں کو مالی اعانت فراہم کرنا</li></ul><h2 id="سادسًا-وسائل-کی-کھلاؤ-کی-نگرانی-اور-تدارک" tabindex="-1">سادسًا. وسائل کی کھلاؤ کی نگرانی اور تدارک <a class="header-anchor" href="#سادسًا-وسائل-کی-کھلاؤ-کی-نگرانی-اور-تدارک" aria-label="Permalink to &quot;سادسًا. وسائل کی کھلاؤ کی نگرانی اور تدارک&quot;">​</a></h2><h3 id="_6-1-نگرانی-کا-طریقہ-کار" tabindex="-1">6.1 نگرانی کا طریقہ کار <a class="header-anchor" href="#_6-1-نگرانی-کا-طریقہ-کار" aria-label="Permalink to &quot;6.1 نگرانی کا طریقہ کار&quot;">​</a></h3><ul><li><strong>اینکر نیٹ ورک ریئل ٹائم نگرانی</strong>: اینکر نیٹ ورک تمام عوامی وسائل کی ترقی، تقسیم، استعمال کی صورتحال کی ریئل ٹائم نگرانی کرتا ہے، اور غیر معمولی بات دریافت کرنے پر بروقت انتباہ کرتا ہے</li><li><strong>وسائل کی انصاف کمیٹی</strong>: خاص طور پر وسائل کی تقسیم کی انصاف اور قانونی حیثیت کی نگرانی کرتی ہے، اور شکایات اور اطلاعیں قبول کرتی ہے</li><li><strong>سماجی نگرانی</strong>: تمام جانداروں کو وسائل کی ترقی اور تقسیم میں نامناسب رویے کی نگرانی اور اطلاع دینے کی ترغیب دینا</li><li><strong>باقاعدگی سے آڈٹ</strong>: ہر سال وسائل کی انتظامیہ کے اداروں کی آزادانہ آڈٹ کرنا، اور آڈٹ کے نتائج معاشرے کے سامنے کھولنا</li></ul><h3 id="_6-2-تدارک-کا-طریقہ-کار" tabindex="-1">6.2 تدارک کا طریقہ کار <a class="header-anchor" href="#_6-2-تدارک-کا-طریقہ-کار" aria-label="Permalink to &quot;6.2 تدارک کا طریقہ کار&quot;">​</a></h3><ul><li><strong>تقسیم کی اپیل</strong>: جن افراد کو وسائل کی تقسیم کے نتائج پر اعتراض ہے وہ وسائل کی انصاف کمیٹی میں نظر ثیزی کے لیے درخواست دے سکتے ہیں</li><li><strong>وسائل کے تنازعات کی ثالثی</strong>: وسائل کے تنازعات کی اینکر عدالت کے ذریعے ثالثی کی جاتی ہے، اور ثالثی کے نتائج کا قانونی اثر ہوتا ہے</li><li><strong>جارحیت سے متاثرہ کی تدارک</strong>: وسائل کی یکجہتی، وسائل کی لوٹ مار وغیرہ رویوں کی وجہ سے نقصان پہنچنے والے افراد اینکر عدالت میں مقدمہ درج کر کے معاوضے کا مطالبہ کر سکتے ہیں</li><li><strong>ہنگامی امداد</strong>: خاص حالات میں (جیسے آفات، جنگیں وغیرہ)، ہنگامی وسائل کی تقسیم کا طریقہ کار شروع کرنا، اور متاثرہ گروہوں کی بنیادی وسائل کی ضروریات کو یقینی بنانا</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سادھائی کے وسائل کی کھلاؤ کا طریقہ کار اینکر سمبیوٹک تہذیب کے معاشی نظام کا بنیادی حصہ ہے۔ یہ &quot;بنیادی ضمانت + زیادہ محنت زیادہ فائدہ + یکجہتی مخالف + پائیدار + کھلا شفاف&quot; پانچ اصولوں کے ذریعے، ایک منصفانہ، موثر، پائیدار وسائل کی تقسیم کا نظام بناتا ہے۔ وسائل کی کھلاؤ کے طریقہ کار کا حتمی مقصد، تمام جانداروں کو یکساں مقدار میں وسائل فراہم کرنا نہیں ہے، بلکہ ہر زندگی کو وسائل تک منصفانہ رسائی کا موقع دینا، وسائل کو سب سے زیادہ قدر تخلیق کرنے کے قابل جگہ کی طرف بہانا، اور پائیدار شرط پر تہذیب کے وسائل کی کل مقدار کو مسلسل بڑھانا ہے۔ جب سادھائی کے وسائل مزید چند لوگوں کے قبضے میں نجی ملکیت نہ رہیں، بلکہ تمام نسلوں کی مشترکہ، چکری طور پر فائدہ اٹھانے والی عوامی دولت بن جائیں، تو &quot;ہر ایک کے پاس راستہ ہے&quot; کے آدرش کو حقیقت میں بدلا جا سکتا ہے، اور تمام نسلوں کی مشترکہ ترقی کے مقصد کو حقیقت میں پورا کیا جا سکتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (زیادہ محنت زیادہ فائدہ کی تقسیم کے اصول)</li><li>08-人人有路保障体系 (ہر ایک کے پاس راستہ ہے ضمانتی نظام)</li><li>22-资源分配联产承包机制 (وسائل کی تقسیم مشترکہ پیداوار معاہدہ کا طریقہ کار)</li></ul>',57)])])}const c=a(o,[["render",d]]);export{b as __pageData,c as default};
